              theta ~ beta(1,1); // uniform prior
              //print("parameter prior applied: lp__=", lp__, ", or p=", exp(lp__));
              for (t in 1:N) {
                  previous_lp <- lp__;
                  y[t] ~ bernoulli(theta); // fit the data
